/* eslint-disable */
import React, { useRef, useState } from "react";

/**
 * NewsStack (smooth)
 * items: [{ img, title, excerpt, href }]
 */
export default function NewsStack({ items = [] }) {
  // positions (fond -> avant)
  const base = [
    { top: 0, left: 0, rotate: 0, z: 10 },
    { top: 28, left: 36, rotate: -2, z: 20 },
    { top: 56, left: 72, rotate: 0.8, z: 30 },
  ];

  const wrapRef = useRef(null);
  const [hovered, setHovered] = useState(null);
  const [tilt, setTilt] = useState({ rx: 0, ry: 0 });

  // petit tilt sur mouvement de souris
  const onMove = (e) => {
    const el = wrapRef.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    const cx = r.left + r.width / 2;
    const cy = r.top + r.height / 2;
    const dx = (e.clientX - cx) / (r.width / 2);
    const dy = (e.clientY - cy) / (r.height / 2);
    const max = 3; // degrés max
    setTilt({ rx: -(dy * max), ry: dx * max });
  };

  const onLeave = () => setTilt({ rx: 0, ry: 0 });

  const motionTransition =
    "transform 520ms cubic-bezier(.2,.8,.2,1), box-shadow 520ms cubic-bezier(.2,.8,.2,1), filter 420ms ease, opacity 420ms ease";

  const cardStyle = (i) => {
    const isHover = hovered === i;
    const reduce =
      window.matchMedia &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const baseTransform = `rotate(${base[i].rotate}deg)`;
    const lift = isHover ? " translateY(-8px) scale(1.045)" : "";
    const tilt3d =
      hovered === i && !reduce
        ? ` rotateX(${tilt.rx}deg) rotateY(${tilt.ry}deg)`
        : "";

    return {
      top: base[i].top,
      left: base[i].left,
      zIndex: isHover ? 60 : base[i].z,
      transform: baseTransform + lift + tilt3d,
      transition: motionTransition,
      willChange: "transform, box-shadow, filter, opacity",
      boxShadow: isHover
        ? "0 22px 48px rgba(0,0,0,.32)"
        : "0 14px 32px rgba(0,0,0,.20)",
      filter: isHover ? "saturate(1.08) contrast(1.04)" : "saturate(.78) brightness(.96)",
      opacity: isHover ? 1 : 0.9,
      // léger décalage temporel (stagger subtil)
      transitionDelay: `${i * 30}ms`,
    };
  };

  return (
    <div
      ref={wrapRef}
      className="relative w-full"
      style={{ height: 380, maxWidth: 560 }}
      onMouseMove={onMove}
      onMouseLeave={onLeave}
    >
      {items.slice(0, 3).map((it, i) => (
        <article
          key={i}
          onMouseEnter={() => setHovered(i)}
          onMouseLeave={() => setHovered(null)}
          className="absolute w-[360px] h-[230px] rounded-xl overflow-hidden bg-white cursor-pointer"
          style={cardStyle(i)}
        >
          <a href={it.href || "#"} className="block h-full w-full relative">
            <img
              src={it.img}
              alt={it.title}
              className="absolute inset-0 w-full h-full object-cover"
              style={{
                transition: "transform 520ms cubic-bezier(.2,.8,.2,1)",
                transform: hovered === i ? "scale(1.03)" : "scale(1.01)",
              }}
            />
            {/* voile bas pour la lisibilité */}
            <div
              className="absolute inset-0 pointer-events-none"
              style={{
                background:
                  "linear-gradient(to top, rgba(0,0,0,.68) 0%, rgba(0,0,0,.06) 60%, rgba(0,0,0,0) 100%)",
              }}
            />
            <div className="absolute left-0 right-0 bottom-0 p-4 text-white">
              <h4 className="text-lg font-semibold leading-tight">{it.title}</h4>
              <p className="text-sm opacity-90 mt-1 line-clamp-2">{it.excerpt}</p>
            </div>
            {/* liseré bleu */}
            <div className="absolute top-2 right-3 h-[88%] w-1 rounded bg-[#5aa4ff]" />
          </a>
        </article>
      ))}
    </div>
  );
}
